//! Retry configuration.

/// Configuration for the bounded exponential retry policy.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound for any single retry delay, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a retry policy with `max_attempts` total attempts
    /// (including the first call), a `base_delay_ms` initial backoff and
    /// an upper delay bound of `max_delay_ms`.
    pub fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    /// Returns the delay in milliseconds to wait before the retry at
    /// `retry_index` (0 = the first retry, after the first failed
    /// attempt).
    ///
    /// The delay doubles for each retry (`base_delay_ms * 2^retry_index`)
    /// and saturates at `max_delay_ms`. The arithmetic is overflow-safe:
    /// exponents above the representable range are clamped, so the
    /// computed value never wraps.
    pub fn retry_delay_ms(&self, retry_index: u32) -> u64 {
        // `1 << 63` is the largest representable power of two; anything
        // above that saturates to `max_delay_ms` anyway.
        let exponent = retry_index.min(63);
        let multiplier = 1u64 << exponent;
        self.base_delay_ms
            .saturating_mul(multiplier)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn first_retry_uses_base_delay() {
        let config = RetryConfig::new(3, 100, 1_000);
        assert_eq!(config.retry_delay_ms(0), 100);
    }

    #[test]
    fn delay_doubles_per_retry() {
        let config = RetryConfig::new(5, 100, 10_000);
        assert_eq!(config.retry_delay_ms(0), 100);
        assert_eq!(config.retry_delay_ms(1), 200);
        assert_eq!(config.retry_delay_ms(2), 400);
        assert_eq!(config.retry_delay_ms(3), 800);
    }

    #[test]
    fn delay_saturates_at_max_delay_ms() {
        let config = RetryConfig::new(10, 100, 500);
        assert_eq!(config.retry_delay_ms(2), 400);
        assert_eq!(config.retry_delay_ms(3), 500);
        assert_eq!(config.retry_delay_ms(50), 500);
    }

    #[test]
    fn huge_exponents_do_not_overflow() {
        let config = RetryConfig::new(u32::MAX, u64::MAX, u64::MAX);
        for index in [63u32, 64, 100, 1_000, u32::MAX] {
            assert_eq!(config.retry_delay_ms(index), u64::MAX);
        }
    }

    #[test]
    fn saturation_wins_when_multiply_would_overflow() {
        let config = RetryConfig::new(100, u64::MAX, 1_000);
        assert_eq!(config.retry_delay_ms(1), 1_000);
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` for transient faults that may be retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transient_errors_are_retryable() {
        assert!(RetryError::Transient("blip".to_string()).is_transient());
    }

    #[test]
    fn permanent_errors_are_not_retryable() {
        assert!(!RetryError::Permanent("bad input".to_string()).is_transient());
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
///
/// The retry policy is configured by `config`:
/// - Only [`RetryError::Transient`] failures are retried; permanent
///   failures return immediately.
/// - `max_attempts` counts the first call, so at most `max_attempts`
///   invocations happen in total.
/// - Delays between attempts follow exponential backoff
///   (`base_delay_ms * 2^retry_index`) and saturate at `max_delay_ms`.
///
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempt = 0u32;
    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(err) if !err.is_transient() => return Err(err),
            Err(err) => {
                // The budget is exhausted: `attempt + 1` calls have been
                // made (attempt is 0-based), so the transient error is
                // returned as-is.
                if attempt.saturating_add(1) >= config.max_attempts {
                    return Err(err);
                }
                sleeper.sleep_ms(config.retry_delay_ms(attempt));
                attempt += 1;
            }
        }
    }
}
